class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<int> nxt(n);
        for (int i = 0; i < n - 1; ++i) nxt[i] = i + 1;
        nxt[n - 1] = 0;
        int dist = n - 1;
        vector<int> ans;
        for (const auto& q : queries) {
            int u = q[0], v = q[1];
            int curr = nxt[u];
            while (curr < v) {
                dist--;
                int temp = nxt[curr];
                nxt[curr] = v;
                curr = temp;
            }
            nxt[u] = max(nxt[u], v);
            ans.push_back(dist);
        }
        return ans;
    }
};

class Solution {
    public int[] shortestDistanceAfterQueries(int n, int[][] queries) {
        int[] nxt = new int[n];
        for (int i = 0; i < n - 1; ++i) nxt[i] = i + 1;
        int dist = n - 1;
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int u = queries[i][0], v = queries[i][1];
            int curr = nxt[u];
            while (curr < v) {
                dist--;
                int temp = nxt[curr];
                nxt[curr] = v;
                curr = temp;
            }
            nxt[u] = Math.max(nxt[u], v);
            ans[i] = dist;
        }
        return ans;
    }
}

var shortestDistanceAfterQueries = function(n, queries) {
    const nxt = new Array(n);
    for (let i = 0; i < n - 1; i++) nxt[i] = i + 1;
    nxt[n - 1] = 0;
    let dist = n - 1;
    const ans = [];
    for (const [u, v] of queries) {
        let curr = nxt[u];
        while (curr < v) {
            dist--;
            const temp = nxt[curr];
            nxt[curr] = v;
            curr = temp;
        }
        nxt[u] = Math.max(nxt[u], v);
        ans.push(dist);
    }
    return ans;
};
